<template>
  <div v-loading="loading" class="archive-panel">
    <template v-if="archive">
      <div class="archive-summary">
        <div><div class="summary-title">{{archive.contractName}}</div><div class="summary-meta">{{archive.contractNo}} · {{archive.year}}年 · {{projectTypeText}}</div></div>
        <div class="summary-progress"><el-progress type="circle" :width="64" :percentage="archive.completionPercent"/><span>{{archive.completedCount}}/{{archive.totalCount}} 项</span></div>
        <el-button type="primary" :loading="downloading" v-hasPermi="['yideyifeng:project-archive:download']" @click="downloadAll"><Icon icon="ep:download"/>一键打包下载</el-button>
      </div>
      <el-form inline class="archive-base">
        <el-form-item label="归档年度"><el-input-number v-model="archive.year" :min="2000" :max="2100"/></el-form-item>
        <el-form-item label="项目类型"><el-select v-model="archive.projectType" class="!w-120px"><el-option label="建设" :value="1"/><el-option label="服务" :value="2"/><el-option label="其他" :value="3"/></el-select></el-form-item><el-form-item label="项目编码"><el-input v-model="archive.projectCode" placeholder="例如 26-001" class="!w-150px"/></el-form-item>
        <el-form-item><el-button v-hasPermi="['yideyifeng:project-archive:update']" @click="saveBase">保存基本信息</el-button></el-form-item>
      </el-form>
      <el-divider content-position="left">实体档案</el-divider>
      <div class="physical-toolbar"><el-tag :type="physicalStatusTag">{{ physicalStatusText }}</el-tag><span>按项目编码定位实体原件，单份文件可独立借阅、归还。</span><el-button type="primary" v-hasPermi="['yideyifeng:project-archive:physical-file']" @click="openFileDialog()"><Icon icon="ep:plus"/>登记实体文件</el-button></div>
      <el-table :data="archive.physicalFiles || []" border size="small" class="!w-100%" empty-text="暂无实体文件登记"><el-table-column prop="fileCode" label="文件编号" width="140"/><el-table-column prop="fileName" label="文件名称" min-width="180"/><el-table-column label="类型" width="80"><template #default="{row}">{{row.copyType===1?'原件':'复印件'}}</template></el-table-column><el-table-column prop="storageLocation" label="存放位置" min-width="130"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===0?'success':'warning'">{{row.status===0?'在库':'借出'}}</el-tag></template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openFileDialog(row)">编辑</el-button><el-button link type="info" @click="openLendingHistory(row)">借还记录</el-button><el-button v-if="row.status===0" link type="primary" v-hasPermi="['yideyifeng:project-archive:lend']" @click="openLendDialog(row)">借出</el-button><el-button v-if="row.status===1" link type="success" v-hasPermi="['yideyifeng:project-archive:return']" @click="returnFile(row)">归还</el-button><el-button v-if="row.status===0" link type="danger" @click="deleteFile(row)">删除</el-button></template></el-table-column></el-table>
      <el-dialog v-model="fileDialogVisible" :title="fileForm.id?'编辑实体文件':'登记实体文件'" width="560px" append-to-body><el-form :model="fileForm" label-width="90px"><el-form-item label="文件编号"><el-input v-model="fileForm.fileCode" placeholder="留空自动生成"/></el-form-item><el-form-item label="文件名称" required><el-input v-model="fileForm.fileName"/></el-form-item><el-form-item label="文件类型"><el-radio-group v-model="fileForm.copyType"><el-radio :value="1">原件</el-radio><el-radio :value="2">复印件</el-radio></el-radio-group></el-form-item><el-form-item label="页数"><el-input-number v-model="fileForm.pageCount" :min="1"/></el-form-item><el-form-item label="存放位置"><el-input v-model="fileForm.storageLocation" placeholder="柜号/盒号/文件夹"/></el-form-item><el-form-item label="备注"><el-input v-model="fileForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="fileDialogVisible=false">取消</el-button><el-button type="primary" @click="savePhysicalFile">保存</el-button></template></el-dialog>
      <el-dialog v-model="historyDialogVisible" title="借出归还记录" width="760px" append-to-body><el-table :data="lendingHistory" border size="small"><el-table-column prop="borrowerName" label="借阅人" width="100"/><el-table-column prop="borrowerDept" label="科室" width="120"/><el-table-column prop="purpose" label="用途" min-width="160"/><el-table-column label="借出时间" width="170"><template #default="{row}">{{formatDateTime(row.lendTime)}}</template></el-table-column><el-table-column label="应归还" width="120"><template #default="{row}">{{formatDateOnly(row.dueDate)}}</template></el-table-column><el-table-column label="归还时间" width="170"><template #default="{row}">{{formatDateTime(row.returnTime)}}</template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="row.status===0?'warning':'success'">{{row.status===0?'借出中':'已归还'}}</el-tag></template></el-table-column></el-table></el-dialog>
      <el-dialog v-model="lendDialogVisible" title="实体文件借出" width="520px" append-to-body><el-form :model="lendForm" label-width="90px"><el-form-item label="借阅人" required><el-input v-model="lendForm.borrowerName"/></el-form-item><el-form-item label="借阅科室"><el-input v-model="lendForm.borrowerDept"/></el-form-item><el-form-item label="借阅用途" required><el-input v-model="lendForm.purpose" type="textarea"/></el-form-item><el-form-item label="应归还日期" required><el-date-picker v-model="lendForm.dueDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="lendForm.lendRemark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="lendDialogVisible=false">取消</el-button><el-button type="primary" @click="lendFile">确认借出</el-button></template></el-dialog>      <el-collapse v-model="activeItems">
        <el-collapse-item v-for="item in archive.items" :key="item.id" :name="item.id">
          <template #title><div class="item-title"><span class="item-number">{{String(item.itemNo).padStart(2,'0')}}</span><span>{{item.itemName}}</span><el-tag :type="statusTag(item.status)" size="small">{{statusText(item.status)}}</el-tag><span class="item-file-count">{{fileCount(item)}} 个补充附件</span></div></template>
          <el-form label-width="90px" class="item-form">
            <el-form-item label="归档状态"><el-radio-group v-model="item.status" @change="saveItem(item, false)"><el-radio-button :value="0">未维护</el-radio-button><el-radio-button :value="1">部分完成</el-radio-button><el-radio-button :value="2">已完成</el-radio-button><el-radio-button :value="3">不适用</el-radio-button></el-radio-group></el-form-item>
            <el-form-item v-if="optionLabels[item.itemNo]" label="分类选项"><el-select v-model="item.optionValue" clearable multiple collapse-tags class="!w-100%" @change="saveItem(item, false)"><el-option v-for="label in optionLabels[item.itemNo]" :key="label" :label="label" :value="label"/></el-select></el-form-item>
            <el-form-item v-if="item.itemNo===7" label="合同附件"><ContractFileList :model-value="archive.contractFileUrls || ''" class="!w-100%"/></el-form-item>
            <el-form-item v-if="item.itemNo===6" label="OA流程"><el-table :data="archive.oaWorkflows" size="small" class="!w-100%" empty-text="尚未关联 OA 流程"><el-table-column prop="requestId" label="请求编号" width="100"/><el-table-column prop="title" label="流程标题" min-width="180"/><el-table-column prop="status" label="状态" width="90"/><el-table-column prop="currentNode" label="当前节点" width="120"/></el-table></el-form-item>
            <el-form-item label="补充附件"><UploadFile v-model="item.fileUrls" :limit="20" :file-size="50" :file-type="fileTypes" @update:model-value="saveItem(item, false)"/></el-form-item>
            <el-form-item label="备注"><el-input v-model="item.remark" type="textarea" :rows="2" maxlength="1000" show-word-limit @blur="saveItem(item, false)"/></el-form-item>
            <el-form-item><el-button type="primary" v-hasPermi="['yideyifeng:project-archive:update']" @click="saveItem(item)">保存本项</el-button></el-form-item>
          </el-form>
        </el-collapse-item>
      </el-collapse>
    </template>
  </div>
</template>
<script setup lang="ts">
import download from '@/utils/download'
import { formatDate } from '@/utils/formatTime'
import {ProjectArchiveApi,type ProjectArchive,type ProjectArchiveItem,type PhysicalArchiveFile} from '@/api/yideyifeng/projectArchive'
import ContractFileList from '../contract/ContractFileList.vue'
const props=defineProps<{contractId?:number;archiveId?:number}>();const emit=defineEmits<{changed:[]}>();const message=useMessage();const loading=ref(false);const downloading=ref(false);const archive=ref<ProjectArchive>();const fileDialogVisible=ref(false);const lendDialogVisible=ref(false);const historyDialogVisible=ref(false);const lendingHistory=ref<any[]>([]);const fileForm=ref<any>({copyType:1,copyCount:1});const lendForm=ref<any>({});const selectedFile=ref<PhysicalArchiveFile>();const activeItems=ref<number[]>([]);const savingItems=new Set<number>();const pendingItems=new Set<number>()
const fileTypes=['jpg','jpeg','png','pdf','doc','docx','xls','xlsx','ppt','pptx','zip','rar','txt']
const optionLabels:Record<number,string[]>={3:['科室需求','政策文件','其他'],5:['直接采购','比价','招投标'],8:['服务','建设','其他'],9:['一次性项目','维保时间','服务周期'],10:['医院转账','其他'],11:['运维记录','运维报告','货物签收','科室签字','其他'],12:['运维记录','验收报告','总结报告','其他'],13:['非固定资产','固定资产','无形资产']}
const formatDateTime=(value?:string)=>value?formatDate(new Date(value),'YYYY年MM月DD日 HH:mm'):'-';const formatDateOnly=(value?:string)=>value?formatDate(new Date(value),'YYYY年MM月DD日'):'-';const physicalStatusText=computed(()=>['未登记','全部在库','部分借出','存在异常'][archive.value?.physicalArchiveStatus||0]);const physicalStatusTag=computed(()=>['info','success','warning','danger'][archive.value?.physicalArchiveStatus||0] as any);const projectTypeText=computed(()=>({1:'建设项目',2:'服务项目',3:'其他项目'}[archive.value?.projectType||1]));const statusText=(v:number)=>['未维护','部分完成','已完成','不适用'][v]||'未维护';const statusTag=(v:number)=>v===2?'success':v===1?'warning':v===3?'info':'danger';const fileCount=(v:ProjectArchiveItem)=>Array.isArray(v.fileUrls)?v.fileUrls.length:(v.fileUrls||'').split(',').filter(Boolean).length
const openLendingHistory=async(row:PhysicalArchiveFile)=>{lendingHistory.value=await ProjectArchiveApi.getPhysicalLendings(row.id);historyDialogVisible.value=true};const openFileDialog=(row?:PhysicalArchiveFile)=>{fileForm.value=row?{...row}:{copyType:1,copyCount:1};fileDialogVisible.value=true};const savePhysicalFile=async()=>{if(!archive.value||!fileForm.value.fileName)return message.warning('请填写文件名称');if(!archive.value.projectCode)return message.warning('请先填写项目编码，例如 26-001');await ProjectArchiveApi.update({id:archive.value.id,year:archive.value.year,projectType:archive.value.projectType,projectCode:archive.value.projectCode});const data={...fileForm.value,archiveId:archive.value.id,copyCount:fileForm.value.copyCount||1};if(data.id)await ProjectArchiveApi.updatePhysicalFile(data);else await ProjectArchiveApi.createPhysicalFile(data);fileDialogVisible.value=false;await load();message.success('实体文件已保存')};const openLendDialog=(row:PhysicalArchiveFile)=>{selectedFile.value=row;lendForm.value={};lendDialogVisible.value=true};const lendFile=async()=>{if(!selectedFile.value||!lendForm.value.borrowerName||!lendForm.value.purpose||!lendForm.value.dueDate)return message.warning('请填写借阅必填项');await ProjectArchiveApi.lendPhysicalFile({...lendForm.value,fileId:selectedFile.value.id});lendDialogVisible.value=false;await load();message.success('文件已借出')};const returnFile=async(row:PhysicalArchiveFile)=>{const records=await ProjectArchiveApi.getPhysicalLendings(row.id);const active=records.find(v=>v.status===0);if(!active)return message.warning('未找到借出记录');await message.confirm('确认该实体文件已经归还？');await ProjectArchiveApi.returnPhysicalFile({lendingId:active.id});await load();message.success('文件已归还')};const deleteFile=async(row:PhysicalArchiveFile)=>{await message.confirm('确认删除该实体文件登记？');await ProjectArchiveApi.deletePhysicalFile(row.id);await load();message.success('已删除')};const load=async()=>{loading.value=true;try{const data=props.archiveId?await ProjectArchiveApi.get(props.archiveId):await ProjectArchiveApi.getByContract(props.contractId!);data.items.forEach((item)=>{item.fileUrls=item.fileUrls||'';if(optionLabels[item.itemNo]&&!Array.isArray(item.optionValue))item.optionValue=(item.optionValue||'').split(',').filter(Boolean)});archive.value=data}finally{loading.value=false}};const saveBase=async()=>{if(!archive.value)return;await ProjectArchiveApi.update({id:archive.value.id,year:archive.value.year,projectType:archive.value.projectType,projectCode:archive.value.projectCode});message.success('归档基本信息已保存');emit('changed')};const saveItem=async(item:ProjectArchiveItem,notify=true)=>{if(savingItems.has(item.id)){pendingItems.add(item.id);return}savingItems.add(item.id);try{await ProjectArchiveApi.updateItem(item);if(notify)message.success(`${item.itemName}已保存`);emit('changed')}finally{savingItems.delete(item.id);if(pendingItems.delete(item.id))void saveItem(item,false)}};const downloadAll=async()=>{if(!archive.value)return;downloading.value=true;try{const data=await ProjectArchiveApi.download(archive.value.id);download.zip(data,`${archive.value.contractName}-项目归档.zip`)}finally{downloading.value=false}}
watch(()=>[props.contractId,props.archiveId],load,{immediate:true})
</script>
<style scoped>
.archive-summary{display:flex;align-items:center;gap:20px;padding:14px 16px;margin-bottom:12px;background:var(--el-fill-color-light);border:1px solid var(--el-border-color-lighter);border-radius:6px}.summary-title{font-size:16px;font-weight:600}.summary-meta{margin-top:6px;color:var(--el-text-color-secondary)}.summary-progress{display:flex;align-items:center;gap:8px;margin-left:auto;color:var(--el-text-color-secondary)}.archive-base{padding:8px 4px}.item-title{display:flex;align-items:center;gap:10px;width:100%;padding-right:12px}.item-number{width:28px;color:var(--el-color-primary);font-weight:600}.item-file-count{margin-left:auto;color:var(--el-text-color-secondary);font-size:12px}.item-form{padding:12px 16px 2px;background:var(--el-fill-color-extra-light)}
</style>
